// Keep the English heading ids on the Korean translation.
//
// article.mdx keeps the same line numbers as docs/original/article.en.mdx, so the
// heading on line N gets the id the English heading on line N had. rehype-slug
// skips headings that already have an id. Translated headings therefore keep
// anchors such as #the-training-marathon, and links between weeks do not break.
// The map is generated by scripts/generate-source-heading-ids.mjs.

import { SOURCE_HEADING_IDS } from './source-heading-ids.data.mjs';

const TARGET = /(^|\/)src\/content\/article\.mdx$/;

export default function remarkSourceHeadingIds() {
  return (tree, file) => {
    const path = String(file?.path ?? file?.history?.[0] ?? '').replace(/\\/g, '/');
    if (!TARGET.test(path)) return;

    const visit = (node) => {
      if (!node || typeof node !== 'object') return;
      if (node.type === 'heading') {
        const id = SOURCE_HEADING_IDS[node.position?.start?.line];
        if (id) {
          node.data = node.data || {};
          node.data.hProperties = { ...(node.data.hProperties || {}), id };
        }
      }
      for (const child of node.children || []) visit(child);
    };

    visit(tree);
  };
}
